import sys, os
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from lib import *
A = "/_plugins/_alerting"
SRC = "compat-alert-src"
sched = {"period": {"interval": 1, "unit": "MINUTES"}}
def qmon(name, **kw):
    m = {"type": "monitor", "name": name, "monitor_type": "query_level_monitor", "enabled": False, "schedule": sched,
         "inputs": [{"search": {"indices": [SRC], "query": {"size": 0, "query": {"match_all": {}}}}}],
         "triggers": [{"query_level_trigger": {"id": "trig-1", "name": "t1", "severity": "1", "condition": {"script": {"source": "ctx.results[0].hits.total.value > 0", "lang": "painless"}}, "actions": []}}]}
    m.update(kw); return m
bucket = qmon("compat-bucket", monitor_type="bucket_level_monitor",
    inputs=[{"search": {"indices": [SRC], "query": {"size": 0, "aggregations": {"composite_agg": {"composite": {"sources": [{"city": {"terms": {"field": "city"}}}]}}}}}}],
    triggers=[{"bucket_level_trigger": {"id": "trig-2", "name": "b1", "severity": "2", "condition": {"buckets_path": {"_count": "_count"}, "parent_bucket_path": "composite_agg", "script": {"source": "params._count > 1", "lang": "painless"}}, "actions": []}}])
doc = {"type": "monitor", "name": "compat-doc", "monitor_type": "doc_level_monitor", "enabled": False, "schedule": sched,
    "inputs": [{"doc_level_input": {"description": "d", "indices": [SRC], "queries": [{"id": "q1", "name": "q1", "query": "city:x", "tags": []}]}}],
    "triggers": [{"document_level_trigger": {"id": "trig-3", "name": "d1", "severity": "1", "condition": {"script": {"source": "query[tag=\"\"]", "lang": "painless"}}, "actions": []}}]}
hook = {"name": "compat-hook", "destination": {"type": "custom_webhook", "custom_webhook": {"url": "http://127.0.0.1:18080/200"}}}
steps = [
 step("create query monitor", "POST", A + "/monitors", qmon("compat-q1"), capture={"mon": "/_id"}),
 step("get monitor", "GET", A + "/monitors/{mon}"),
 step("get monitor head", "HEAD", A + "/monitors/{mon}"),
 step("get missing monitor", "GET", A + "/monitors/nope"),
 step("create duplicate name", "POST", A + "/monitors", qmon("compat-q1"), capture={"dup": "/_id"}),
 step("create with if_seq_no", "PUT", A + "/monitors/{mon}", qmon("compat-q1", enabled=False), {"if_seq_no": "0", "if_primary_term": "1"}),
 step("update with stale seq_no", "PUT", A + "/monitors/{mon}", qmon("compat-q1"), {"if_seq_no": "0", "if_primary_term": "1"}),
 step("update without seq_no", "PUT", A + "/monitors/{mon}", qmon("compat-q1")),
 step("update missing", "PUT", A + "/monitors/nope", qmon("compat-q1"), {"if_seq_no": "0", "if_primary_term": "1"}),
 step("create interval schedule days", "POST", A + "/monitors", qmon("compat-q2", schedule={"period": {"interval": 2, "unit": "DAYS"}}), capture={"mon2": "/_id"}),
 step("create cron schedule", "POST", A + "/monitors", qmon("compat-q3", schedule={"cron": {"expression": "0 * * * *", "timezone": "UTC"}}), capture={"mon3": "/_id"}),
 step("create bad cron", "POST", A + "/monitors", qmon("compat-bad-cron", schedule={"cron": {"expression": "nope", "timezone": "UTC"}})),
 step("create bad unit", "POST", A + "/monitors", qmon("compat-bad-unit", schedule={"period": {"interval": 1, "unit": "FORTNIGHTS"}})),
 step("create interval zero", "POST", A + "/monitors", qmon("compat-zero", schedule={"period": {"interval": 0, "unit": "MINUTES"}})),
 step("create without name", "POST", A + "/monitors", {k: v for k, v in qmon("x").items() if k != "name"}),
 step("create without inputs", "POST", A + "/monitors", qmon("compat-noin", inputs=[]), capture={"noin": "/_id"}),
 step("create unknown index", "POST", A + "/monitors", qmon("compat-unk", inputs=[{"search": {"indices": ["compat-nope"], "query": {"size": 0, "query": {"match_all": {}}}}}])),
 step("create unknown monitor_type", "POST", A + "/monitors", qmon("compat-unk-type", monitor_type="nope")),
 step("create bad trigger script", "POST", A + "/monitors", qmon("compat-badtrig", triggers=[{"query_level_trigger": {"id": "trig-4", "name": "t", "severity": "1", "condition": {"script": {"source": "ctx.nope(", "lang": "painless"}}, "actions": []}}]), capture={"badscript": "/_id"}),
 step("create bad severity", "POST", A + "/monitors", qmon("compat-badsev", triggers=[{"query_level_trigger": {"id": "trig-5", "name": "t", "severity": "9", "condition": {"script": {"source": "true", "lang": "painless"}}, "actions": []}}]), capture={"badsev": "/_id"}),
 step("create with action to a missing destination", "POST", A + "/monitors", qmon("compat-badact", triggers=[{"query_level_trigger": {"id": "trig-6", "name": "t", "severity": "1", "condition": {"script": {"source": "true", "lang": "painless"}}, "actions": [{"id": "act-1", "name": "a", "destination_id": "nope", "message_template": {"source": "x", "lang": "mustache"}, "throttle_enabled": False, "subject_template": {"source": "s", "lang": "mustache"}}]}}]), capture={"badact": "/_id"}),
 step("create bucket monitor", "POST", A + "/monitors", bucket, capture={"bmon": "/_id"}),
 step("create doc monitor", "POST", A + "/monitors", doc, capture={"dmon": "/_id"}),
 step("get bucket monitor", "GET", A + "/monitors/{bmon}"),
 step("get doc monitor", "GET", A + "/monitors/{dmon}"),
 step("search monitors", "POST", A + "/monitors/_search", {"query": {"match_all": {}}, "sort": [{"monitor.name.keyword": "asc"}]}),
 step("search monitors by name", "POST", A + "/monitors/_search", {"query": {"term": {"monitor.name.keyword": "compat-q2"}}}),
 step("search monitors with size 0", "POST", A + "/monitors/_search", {"size": 0, "query": {"match_all": {}}}),
 step("search monitors GET", "GET", A + "/monitors/_search", query={"q": "monitor.name:compat-q2"}),
 step("execute dryrun", "POST", A + "/monitors/{mon}/_execute", query={"dryrun": "true"}),
 step("execute dryrun with a body monitor", "POST", A + "/monitors/_execute", qmon("compat-adhoc"), {"dryrun": "true"}),
 step("execute bucket dryrun", "POST", A + "/monitors/{bmon}/_execute", query={"dryrun": "true"}),
 step("execute doc dryrun", "POST", A + "/monitors/{dmon}/_execute", query={"dryrun": "true"}),
 step("execute missing", "POST", A + "/monitors/nope/_execute", query={"dryrun": "true"}),
 step("execute with period_end", "POST", A + "/monitors/{mon}/_execute", {"period_end": "2026-01-01T00:00:00Z"}, {"dryrun": "true"}),
 step("execute for real", "POST", A + "/monitors/{mon}/_execute"),
 step("execute failing search", "POST", A + "/monitors/_execute", qmon("compat-bad-search", inputs=[{"search": {"indices": [SRC], "query": {"size": 0, "query": {"nope": {}}}}}]), {"dryrun": "true"}),
 step("execute trigger error", "POST", A + "/monitors/_execute", qmon("compat-trig-error", triggers=[{"query_level_trigger": {"id": "trig-7", "name": "t", "severity": "1", "condition": {"script": {"source": "ctx.results[0].nope.nope > 1", "lang": "painless"}}, "actions": []}}]), {"dryrun": "true"}),
 step("destinations list", "GET", A + "/destinations"),
 step("destinations missing id", "GET", A + "/destinations/nope"),
 step("email accounts search", "POST", A + "/destinations/email_accounts/_search", {"query": {"match_all": {}}}),
 step("alerts list", "GET", A + "/monitors/alerts", capture={"alert": "/alerts/0/id"}),
 step("alerts of a monitor", "GET", A + "/monitors/alerts", query={"monitorId": "{mon}"}),
 step("alerts by severity", "GET", A + "/monitors/alerts", query={"severityLevel": "1", "alertState": "ACTIVE"}),
 step("alerts bad alertState", "GET", A + "/monitors/alerts", query={"alertState": "nope"}),
 step("alerts sort and paging", "GET", A + "/monitors/alerts", query={"sortString": "monitor_name.keyword", "sortOrder": "asc", "size": "5", "startIndex": "0"}),
 step("acknowledge the alert", "POST", A + "/monitors/{mon}/_acknowledge/alerts", {"alerts": ["{alert}"]}),
 step("acknowledge it again", "POST", A + "/monitors/{mon}/_acknowledge/alerts", {"alerts": ["{alert}"]}),
 step("alerts after acknowledge", "GET", A + "/monitors/alerts", query={"monitorId": "{mon}"}),
 step("acknowledge unknown alert", "POST", A + "/monitors/{mon}/_acknowledge/alerts", {"alerts": ["nope"]}),
 step("acknowledge on missing monitor", "POST", A + "/monitors/nope/_acknowledge/alerts", {"alerts": ["nope"]}),
 step("findings", "GET", A + "/findings/_search"),
 step("findings of a monitor", "GET", A + "/findings/_search", query={"monitor_id": "{dmon}"}),
 step("stats", "GET", A + "/stats"),
 step("settings", "GET", "/_cluster/settings", query={"include_defaults": "true", "filter_path": "defaults.plugins.alerting.*"}),
 step("legacy route", "GET", "/_opendistro/_alerting/monitors/{mon}"),
 step("delete monitor", "DELETE", A + "/monitors/{mon}"),
 step("delete again", "DELETE", A + "/monitors/{mon}"),
 step("get deleted", "GET", A + "/monitors/{mon}"),
 step("delete bucket", "DELETE", A + "/monitors/{bmon}"),
 step("delete doc", "DELETE", A + "/monitors/{dmon}"),
 step("delete mon2", "DELETE", A + "/monitors/{mon2}"),
 step("delete mon3", "DELETE", A + "/monitors/{mon3}"),
 step("delete duplicate", "DELETE", A + "/monitors/{dup}"),
 step("delete without inputs", "DELETE", A + "/monitors/{noin}"),
 step("delete bad script", "DELETE", A + "/monitors/{badscript}"),
 step("delete bad severity", "DELETE", A + "/monitors/{badsev}"),
 step("delete bad action", "DELETE", A + "/monitors/{badact}"),
 step("search after deletes", "POST", A + "/monitors/_search", {"query": {"match_all": {}}}),
]
VOL = ["took", "_seq_no", "_primary_term", "enabled_time", "last_update_time", "execution_time", "start_time", "end_time", "period_start", "period_end", "last_run_context", "run_id", "trigger_run_result_id", "execution_id", "acknowledged_time", "last_notification_time", "max_score", "_score", "id", "last_full_sweep_time_millis"]
nd = "".join(__import__("json").dumps(x) + "\n" for i, c in enumerate(["x", "x", "y", "z"]) for x in ({"index": {"_id": str(i)}}, {"city": c, "n": i}))
run(sys.argv[1:], "alerting routes", "The stock Alerting plugin's monitor, execute, destination, alert and finding routes: every monitor type, the validation messages and the dry run results. Generated ids are placeholders.",
    steps, volatile=VOL,
    cleanup=[("DELETE", "/" + SRC, None, {"ignore_unavailable": "true"})] + [("POST", "/" + i + "/_delete_by_query", {"query": {"match_all": {}}}, {"refresh": "true", "ignore_unavailable": "true"}) for i in (".opendistro-alerting-config", ".opendistro-alerting-alerts", ".opendistro-alerting-alert-history-write", ".opensearch-alerting-finding-history-write")],
    setup=[("PUT", "/" + SRC, {"settings": {"number_of_shards": 1, "number_of_replicas": 0}, "mappings": {"properties": {"city": {"type": "keyword"}, "n": {"type": "integer"}}}}),
           ("POST", "/" + SRC + "/_bulk", None, {"refresh": "true"}, nd)],
    setup_note=f"index {SRC}: one shard, four documents (city x, x, y, z; n 0 to 3)")
